head.script:
// 테스트 설명, 유효성 값 설정 (_3: singleSelect=true 일때 setSelectedIndex() 첫 번째 인덱스만 적용 검증)
scwin.tData = {
    "description" : "[multiselect > P > separator]<br/>Multiselect 컴포넌트에서 두 개 이상의 아이템을 선택했을때 Value 값을 구분하는 구분자를 설정합니다.",
    "validation" : [
        "singleSelect=true 일때 setSelectedIndex() 메소드 실행 시 separator 로 분리한 인덱스 배열 중 첫 번째 항목만 선택 상태로 적용합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, singleSelect=true + separator 속성 적용)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cSeparator = con_separator.getText();

    let properties = {};
    properties.singleSelect = "true";
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="target1 : singleSelect=true, separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + ']"', '', 'label1');
    $c.gcm.createBasicMultiSelect(cList);
};



// setSelectedIndex - separator 로 구분된 다중 인덱스 string 입력 (예: "0,1,2")
scwin.btn_setSelectedIndex_onclick = function (e) {
    let cSeparator = con_separator.getText();
    let strSep = (cSeparator === "" ? " " : cSeparator);
    let strIndex = "0" + strSep + "1" + strSep + "2";
    target1.setSelectedIndex(strIndex);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('" + strIndex + "') 호출 완료");
};



// getValue() - 첫 번째 인덱스 값만 적용되어 있는지 확인
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : [" + target1.getValue() + "]");
};



// getSelectedIndex() - 첫 번째 인덱스만 적용되어 있는지 확인
scwin.btn_getSelectedIndex_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};
